import {GitHubAvatar} from '@github-ui/github-avatar'
import {AvatarStack} from '@primer/react'

import type {Requester} from '../types'

export interface RequesterAvatarsProps {
  requesters: Requester[]
  /** Muted text shown next to the stack, e.g. "3 members requested additional budget". */
  children: React.ReactNode
}

/**
 * Avatar stack of recent requesters with a short summary, shown under
 * enterprise add-on and budget request rows.
 */
export function RequesterAvatars({requesters, children}: RequesterAvatarsProps) {
  return (
    <div className="d-flex flex-items-center mt-2">
      {requesters.length > 0 && (
        <AvatarStack disableExpand style={{pointerEvents: 'none'}}>
          {requesters.map(requester => (
            <GitHubAvatar key={requester.login} src={requester.avatarUrl} alt={requester.login} size={20} />
          ))}
        </AvatarStack>
      )}
      <span className="color-fg-muted f6">{children}</span>
    </div>
  )
}
