import {verifiedFetch} from '@github-ui/verified-fetch'

/**
 * Create a member feature request on behalf of the current user
 * (POST /orgs/:org/member_feature_request).
 */
export async function createMemberRequest(requestPath: string, feature: string): Promise<void> {
  const response = await verifiedFetch(requestPath, {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({feature}),
  })
  if (!response.ok) {
    throw new Error('Failed to create request')
  }
}

/**
 * Remove the current user's member feature request
 * (DELETE /orgs/:org/member_feature_request?feature=...).
 */
export async function removeMemberRequest(requestPath: string, feature: string): Promise<void> {
  const response = await verifiedFetch(`${requestPath}?feature=${encodeURIComponent(feature)}`, {
    method: 'DELETE',
  })
  if (!response.ok) {
    throw new Error('Failed to cancel request')
  }
}

/**
 * Submit a primary CTA form (e.g. enabling a Copilot policy or allowing an
 * organization to assign seats). Mirrors the form submissions the ERB page
 * performed with hidden inputs.
 */
export async function submitCtaForm(url: string, method: string, fields: Record<string, string>): Promise<void> {
  const response = await verifiedFetch(url, {
    method: method.toUpperCase(),
    headers: {
      Accept: 'application/json',
      'Content-Type': 'application/x-www-form-urlencoded',
    },
    body: new URLSearchParams(fields),
  })
  if (!response.ok) {
    throw new Error('Failed to submit')
  }
}

export type SubscriptionUpdate = {type: 'watching'} | {type: 'ignoring'} | {type: 'custom'; features: string[]}

/**
 * Update the current user's member request notification subscription
 * (Orgs::Settings::MemberFeatureRequests::SubscriptionsController).
 */
export async function updateSubscription(subscriptionPath: string, update: SubscriptionUpdate): Promise<void> {
  let method: string
  const body = new URLSearchParams()
  switch (update.type) {
    case 'watching':
      method = 'POST'
      break
    case 'ignoring':
      method = 'DELETE'
      break
    case 'custom':
      method = 'PATCH'
      for (const feature of update.features) {
        body.append('features[]', feature)
      }
      break
  }

  const response = await verifiedFetch(subscriptionPath, {
    method,
    headers: {
      Accept: 'application/json',
      'Content-Type': 'application/x-www-form-urlencoded',
    },
    body,
  })
  if (!response.ok) {
    throw new Error('Failed to update subscription')
  }
}
