import {Label, Link} from '@primer/react'

import {type AddonRequest, analyticsAttribute, pluralize, type RequestCard} from '../types'
import {AddonActions} from './AddonActions'
import {requestIcon} from './request-icons'
import {RequesterAvatars} from './RequesterAvatars'
import {RequestRow} from './RequestRow'

/**
 * A feature or add-on request row: feature icon, name, description with a
 * docs link, and the aggregated request count. Add-on rows can additionally
 * carry requester avatars + requesting orgs (enterprise scope) or action CTAs
 * (organization scope).
 */
export function RequestCardRow({card}: {card: RequestCard | AddonRequest}) {
  const addon = 'actions' in card ? card : null
  const Icon = requestIcon(card.icon)

  return (
    <RequestRow
      id={card.key}
      leadingVisual={
        <span className="d-flex flex-row circle p-2 color-bg-subtle color-fg-muted">
          {/* eslint-disable-next-line react-hooks/static-components -- requestIcon returns one of a fixed set of module-level octicons */}
          <Icon />
        </span>
      }
      title={
        <>
          <span className="h4 mr-2">{card.name}</span>
          {addon?.showNewBadge && <Label variant="accent">New</Label>}
        </>
      }
      description={
        <p className="color-fg-muted mb-0">
          {card.description}{' '}
          <Link inline href={card.docsUrl} data-analytics-event={analyticsAttribute(card.docsAnalytics)}>
            View {card.name} docs
          </Link>
        </p>
      }
      figure={card.count}
      figureLabel={pluralize(card.count, 'request')}
    >
      {addon?.requesters && addon.requestedInText && (
        <RequesterAvatars requesters={addon.requesters}>{addon.requestedInText}</RequesterAvatars>
      )}
      {addon?.actions && <AddonActions actions={addon.actions} />}
    </RequestRow>
  )
}
