import type {WatchSettings} from '../types'
import {WatchButton} from './WatchButton'

export interface SectionHeadingProps {
  id: string
  title: string
  description?: React.ReactNode
  /** Renders the notification subscription menu next to the heading (organization scope). */
  watch?: WatchSettings | null
}

export function SectionHeading({id, title, description, watch}: SectionHeadingProps) {
  return (
    <div className="Subhead">
      <h2 className="Subhead-heading" data-testid={`member-requests-heading-${id}`}>
        {title}
      </h2>
      {watch && (
        <div className="Subhead-actions">
          <WatchButton watch={watch} />
        </div>
      )}
      {description ? <div className="Subhead-description">{description}</div> : null}
    </div>
  )
}
