import {LinkExternalIcon} from '@primer/octicons-react'
import {Button} from '@primer/react'
import {useSyncExternalStore} from 'react'

import {analyticsAttribute, type EntityInfo, type UpgradeBannerInfo} from '../types'

const noopSubscribe = () => () => {}

/**
 * "Unlock <plan> Features" hero row at the top of the organization feature
 * requests list, with the upgrade (or enterprise trial) CTA.
 */
export function UpgradeBanner({upgrade, entity}: {upgrade: UpgradeBannerInfo; entity: EntityInfo}) {
  // The hero background CSS keys off the page color mode, which is only known
  // client-side; the stylesheet falls back to prefers-color-scheme until then.
  const colorMode = useSyncExternalStore(
    noopSubscribe,
    () => document.documentElement.getAttribute('data-color-mode') ?? undefined,
    () => undefined,
  )

  return (
    <li
      className="Box-row member-requests-hero-bg"
      data-color-mode={colorMode}
      data-testid="member-requests-upgrade-banner"
    >
      <div className="d-flex flex-row position-relative">
        <div className="col-12 col-md-8 mx-auto mx-md-0">
          <h3 className="unlock-feature-banner lh-condensed">
            <span className="color-fg-done">Unlock</span> {upgrade.targetPlanLabel} Features
          </h3>
          <p className="color-fg-muted">
            {entity.name} is on the <span className="text-bold">{upgrade.currentPlanName} organization plan</span>
          </p>
          <div className="d-flex flex-column flex-sm-row flex-wrap gap-2">
            <Button
              as="a"
              variant="primary"
              href={upgrade.ctaUrl}
              data-testid={`member-requests-${upgrade.ctaKind}-cta`}
              data-analytics-event={analyticsAttribute(upgrade.ctaAnalytics)}
            >
              {upgrade.ctaText}
            </Button>
            <Button
              as="a"
              href={upgrade.customerStoryUrl}
              target="_blank"
              rel="noopener noreferrer"
              leadingVisual={LinkExternalIcon}
              data-testid="member-requests-watch-customer-story-cta"
              data-analytics-event={analyticsAttribute(upgrade.customerStoryAnalytics)}
            >
              Watch customer story
            </Button>
          </div>
        </div>
      </div>
    </li>
  )
}
