import {LinkExternalIcon} from '@primer/octicons-react'
import {Button, Link} from '@primer/react'
import {useState} from 'react'

import {createMemberRequest, removeMemberRequest, submitCtaForm} from '../api'
import {type AddonActions as AddonActionsData, analyticsAttribute} from '../types'

/**
 * CTAs under an add-on request row on the organization page. React port of
 * Organizations::MemberRequests::AddonActionsComponent (and the
 * FeatureRequestComponent it renders for enterprise-billed requests).
 */
export function AddonActions({actions}: {actions: AddonActionsData}) {
  return (
    <div className="d-flex flex-row flex-wrap gap-2 mt-2">
      {actions.enterpriseRequest ? (
        <EnterpriseRequestButton enterpriseRequest={actions.enterpriseRequest} />
      ) : (
        actions.primaryCta && <PrimaryCtaButton primaryCta={actions.primaryCta} />
      )}
      {actions.secondaryCta && (
        <Button
          as="a"
          href={actions.secondaryCta.url}
          target="_blank"
          rel="noopener noreferrer"
          leadingVisual={LinkExternalIcon}
          data-testid="addon-see-how-it-works-cta"
          data-analytics-event={analyticsAttribute(actions.secondaryCta.analytics)}
        >
          {actions.secondaryCta.text}
        </Button>
      )}
    </div>
  )
}

function EnterpriseRequestButton({
  enterpriseRequest,
}: {
  enterpriseRequest: NonNullable<AddonActionsData['enterpriseRequest']>
}) {
  const [state, setState] = useState(enterpriseRequest.state)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState<string | null>(null)

  async function request() {
    setBusy(true)
    setError(null)
    try {
      await createMemberRequest(enterpriseRequest.requestPath, enterpriseRequest.featureKey)
      setState('requested')
    } catch {
      setError('Something went wrong creating your request. Please try again.')
    } finally {
      setBusy(false)
    }
  }

  async function removeRequest() {
    setBusy(true)
    setError(null)
    try {
      await removeMemberRequest(enterpriseRequest.requestPath, enterpriseRequest.featureKey)
      setState('none')
    } catch {
      setError('Something went wrong removing your request. Please try again.')
    } finally {
      setBusy(false)
    }
  }

  if (state === 'dismissed') {
    return (
      <div data-testid="enterprise-request-dismissed">
        <p>
          Your request for {enterpriseRequest.featureName} was declined by an admin on {enterpriseRequest.dismissedAt}.
        </p>
        <p>
          <Link inline href={enterpriseRequest.contactAdminUrl}>
            Contact an admin
          </Link>{' '}
          for more details around their decision.
        </p>
      </div>
    )
  }

  if (state === 'requested') {
    return (
      <div className="d-flex flex-items-center">
        <Button
          variant="invisible"
          className="color-fg-danger"
          disabled={busy}
          onClick={() => void removeRequest()}
          data-testid="enterprise-request-remove-cta"
        >
          Remove request
        </Button>
        <ActionError error={error} />
      </div>
    )
  }

  return (
    <div className="d-flex flex-items-center">
      <Button
        disabled={busy}
        onClick={() => void request()}
        data-testid="enterprise-request-cta"
        data-analytics-event={analyticsAttribute(enterpriseRequest.analytics)}
      >
        Ask enterprise owners for access
      </Button>
      <ActionError error={error} />
    </div>
  )
}

function ActionError({error}: {error: string | null}) {
  if (!error) return null
  return (
    <span role="alert" className="color-fg-danger f6 ml-2">
      {error}
    </span>
  )
}

function PrimaryCtaButton({primaryCta}: {primaryCta: NonNullable<AddonActionsData['primaryCta']>}) {
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState<string | null>(null)

  async function submit() {
    const form = primaryCta.form
    if (!form) return
    setBusy(true)
    setError(null)
    try {
      await submitCtaForm(primaryCta.url, form.method, form.fields)
      // The ERB page performed a full form submission here; reload so the
      // page reflects the new policy/seat assignment state.
      window.location.reload()
    } catch {
      setError('Something went wrong. Please try again.')
      setBusy(false)
    }
  }

  if (primaryCta.form) {
    return (
      <div className="d-flex flex-items-center">
        <Button
          disabled={busy}
          onClick={() => void submit()}
          data-testid="addon-primary-cta"
          data-analytics-event={analyticsAttribute(primaryCta.analytics)}
        >
          {primaryCta.text}
        </Button>
        <ActionError error={error} />
      </div>
    )
  }

  return (
    <Button
      as="a"
      href={primaryCta.url}
      data-testid="addon-primary-cta"
      data-analytics-event={analyticsAttribute(primaryCta.analytics)}
    >
      {primaryCta.text}
    </Button>
  )
}
