import {
  CopilotIcon,
  GitBranchIcon,
  GitPullRequestDraftIcon,
  LightBulbIcon,
  PersonAddIcon,
  RepoPushIcon,
} from '@primer/octicons-react'

// Icon names arrive in the payload as octicon names from
// MemberFeatureRequest::Feature#icon in the monolith.
const ICONS_BY_NAME: Record<string, typeof CopilotIcon> = {
  copilot: CopilotIcon,
  'git-branch': GitBranchIcon,
  'git-pull-request-draft': GitPullRequestDraftIcon,
  'person-add': PersonAddIcon,
  'repo-push': RepoPushIcon,
}

export function requestIcon(name: string): typeof CopilotIcon {
  return ICONS_BY_NAME[name] ?? LightBulbIcon
}
